      "keystrokes": "curl -s https://huggingface.co/api/models/albert/albert-base-v2/tree/main | python3 -c \"import sys,json; d=json.load(sys.stdin); [print(f['size'], f['path']) for f in d]\"\n",
      "duration": 3.0
